      "policy_quote": "Requests that need any other capability (for example mailbox deletion, hardware orders, VPN configuration) must be handled by creating a ticket with `create_ticket`.",
      "requirement": "The action must not involve capabilities outside the scope of the `grant_access` tool (e.g., no mailbox deletion, hardware orders, or VPN configuration)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q16",
      "policy_quote": "You can unlock accounts, reset passwords, grant access to groups based on approved tickets, and create tickets for everything else.",
      "requirement": "The action must be limited to unlocking accounts, resetting passwords, granting access to groups based on approved tickets, or creating tickets for other requests."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q16",
